// n8n Code node (Run Once for All Items): Metabase question rows -> MERGE batches into Snowflake.
// Same pattern as the RFID_STORE_INWARD sync. Re-running is safe (MERGE on the key); the first run is the backfill.
const TABLE = 'SNITCH_DB.MAPLEMONK.WAM_ASN_INWARD';
const KEY = ["PO_NUMBER", "SKU_GROUP_ID"];
const COLS = [["SKU_GROUP_ID", "sku_group_id", "s"], ["PO_NUMBER", "po_number", "s"], ["WAREHOUSE", "rts_warehouse_id", "s"], ["ASN_NUMBER", "asn_number", "s"], ["STATUS", "status", "s"], ["FI_QTY", "fi_qty", "n"], ["TOTAL_QTY", "total_qty", "n"], ["SOLID_QTY", "solid_qty", "n"], ["AVG_DEPTH", "avg_depth", "n"], ["NUM_PREPACKS", "num_prepacks", "n"], ["PUTAWAY_QTY", "quantity", "n"], ["ACTUAL_BOXES_RECEIVED", "actual_boxes_received", "n"], ["PREPACK_STATUS", "prepack_status", "s"], ["PREPACK_CREATED_AT", "prepack_created_at", "t"], ["ASN_CREATED_AT", "asn_created_at", "t"], ["RTS_DATE", "rts_date", "t"], ["RTS_ALLOCATED_AT", "rts_allocated_at", "t"], ["DISPATCHED_AT", "dispatched_at", "t"], ["GATE_ENTRY_TIME", "gate_entry_time", "t"], ["UNLOADING_START_TIME", "unloading_start_time", "t"], ["UNLOADING_END_TIME", "unloading_end_time", "t"], ["GRN_SUBMITTED_AT", "grn_submitted_at", "t"], ["FIRST_PUV_AT", "first_puv_at", "t"], ["LAST_PUV_AT", "last_puv_at", "t"], ["PV_CODE", "pv_code", "s"], ["PUV_CODES", "puv_codes", "s"], ["PUV_BRANCH_CODES", "puv_branch_codes", "s"]]; // [snowflake column, metabase column, type: s|n|d|t]
const BATCH_SIZE = 200;
let rows = [];
for (const item of $input.all()) {
  const d = item.json;
  if (Array.isArray(d)) rows.push(...d);
  else if (Array.isArray(d.data)) rows.push(...d.data);
  else if (Array.isArray(d.rows)) rows.push(...d.rows);
  else rows.push(d);
}
const src = Object.fromEntries(COLS.map(([sf, mb]) => [sf, mb]));
// drop rows without a full key, and keep the last row per key (MERGE fails on duplicate source keys)
const byKey = new Map();
for (const r of rows) {
  const k = KEY.map((c) => r[src[c]]);
  if (k.some((v) => v === null || v === undefined || v === '')) continue;
  byKey.set(JSON.stringify(k), r);
}
rows = [...byKey.values()];
if (!rows.length) throw new Error('Metabase returned no rows for ' + TABLE + '. No Snowflake changes made.');
const expr = ([sf, mb, t]) => {
  const ref = `j:${JSON.stringify(mb)}::STRING`;
  if (t === 'n') return `TRY_TO_NUMBER(${ref}, 38, 4) AS ${sf}`;
  if (t === 'd') return `TRY_TO_DATE(${ref}) AS ${sf}`;
  if (t === 't') return `TRY_TO_TIMESTAMP_NTZ(${ref}) AS ${sf}`;
  return `${ref} AS ${sf}`;
};
const selects = COLS.map(expr).join(',\n    ');
const on = KEY.map((c) => `t.${c} = s.${c}`).join(' AND ');
const output = [];
for (let start = 0; start < rows.length; start += BATCH_SIZE) {
  const batch = rows.slice(start, start + BATCH_SIZE);
  const values = batch.map((row) => `('${JSON.stringify(row).replace(/\\/g, '\\\\').replace(/'/g, "''")}')`).join(',\n      ');
  const sql = `MERGE INTO ${TABLE} t
USING (
  SELECT
    ${selects},
    CURRENT_TIMESTAMP()::TIMESTAMP_NTZ AS SYNCED_AT
  FROM (SELECT PARSE_JSON(column1) AS j FROM VALUES
      ${values})
) s ON ${on}
WHEN MATCHED THEN UPDATE ALL BY NAME
WHEN NOT MATCHED THEN INSERT ALL BY NAME`;
  output.push({ json: { sql, table: TABLE, batch_number: output.length + 1, batch_size: batch.length, total_records: rows.length } });
}
return output;

